EXE="/workspace/executable"
def test(content):
    open("/tmp/probe.txt","w").write(content)
    r = subprocess.run([EXE, "/tmp/probe.txt"], capture_output=True, text=True)
    return r.returncode!=0

prefixes = [
 "sk-", "sk-proj-", "SG.", "pypi-", "ya29.", "sq0atp-", "sq0csp-",
 "sk_test_", "rk_test_", "pk_live_", "pk_test_", "gldt-", "glpt-", "glrt-",
 "gloas-", "hf_", "xapp-", "dop_v1_", "shpat_", "shpss_", "gsk_",
 "AC", "SK", "heroku", "twilio", "sendgrid", "mailchimp",
 "AKIA", "ASIA", "ABIA", "aws_", "ssh-rsa ", "eyJ", "Bearer ",
 "ghp_", "gho_", # control (should be SECRET at 36)
]

for prefix in prefixes:
    found=False
    for n in [10,20,22,24,30,32,35,36,40,43,48,60,82]:
        for charset, suffix in [
            ("a", "a"*n),
            ("mixed", "aB3dE5gH7jK9mN1pQ3rS5tU7vW9xY1Z2aB4cDEFGHIJ1234567890"[:n]),
            ("digits", "1"*n),
        ]:
