            if test(content):
                print(f"{prefix:15} n={n:2} charset={charset:5} => SECRET [{content[:60]}]")
                found=True
                break
        if found:
            break
    if not found:
        # try with dots/dashes for SG etc
        if prefix=="SG.":
            for n1,n2 in [(22,43),(20,30)]:
                content = prefix+"a"*n1+".b"*(n2//2)
                if test(content):
                    print(f"SG. with dots => SECRET [{content[:60]}]")
                    found=True
                    break
        if not found:
            print(f"{prefix:15} => CLEAN for all lengths")
