import subprocess, math
from collections import Counter
EXE="/workspace/executable"
def test_add(val):
    open("/tmp/probe.txt","w").write(f'my-{val}')
    r = subprocess.run([EXE, "--additional-pattern", "my-(.*)", "/tmp/probe.txt"], capture_output=True, text=True)
    return r.returncode!=0
def ent(s):
    c=Counter(s)
    n=len(s)
    return -sum((v/n)*math.log2(v/n) for v in c.values())

