fn walk_and_scan(root: &Path, re: &regex::bytes::Regex, secrets_matcher: &ignore::gitignore::Gitignore, ignore_secrets: &std::collections::HashSet<Vec<u8>>, only_matching: bool, strict_ignore: bool, out: &mut dyn Write, found: &mut bool) {
