    let walker = ignore::WalkBuilder::new(root)
        .hidden(true)
        .git_ignore(true)
        .git_global(true)
        .git_exclude(true)
        .parents(true)
        .ignore(true)
        .follow_links(false)
        .build();
    for entry in walker {
        match entry {
            Err(e) => {
                // Walk error (e.g., permission denied, loop, etc.)? Original prints "<path>: <error>" to stderr? For permission denied on file inside dir, it printed "<path>: Permission denied (os error 13)" to stderr. Good. For walk errors, e is ignore::Error with path? e.path() and e.io_error()? Let's just print e to stderr? Original format is "<path>: <io error>"? For walk permission error on file, it printed "/tmp/perm_test/noread.txt: Permission denied (os error 13)" - that's path + io error. For walk, e contains path. We should replicate.
                // ignore::Error Display? It might already be "Permission denied"? Need to handle.
                // For now, if e.path() exists, print "{}: {}", path.display(), e.io_error().unwrap_or?
                if let Some(p) = e.path() {
