fn scan_file(path: &Path, display: &str, re: &regex::bytes::Regex, ignore_secrets: &std::collections::HashSet<Vec<u8>>, only_matching: bool, out: &mut dyn Write, found: &mut bool) {
    let data = match std::fs::read(path) {
        Ok(d) => d,
        Err(e) => {
            let _ = writeln!(std::io::stderr(), "{}: {}", display, e);
            return;
        }
