    // Original likely splits on \n and strips trailing \r? For Windows files with \r\n, line content before \r? The private key pattern uses $ which should match before \r? If file has \r\n, line with \r at end would be "-----BEGIN...-----\r" without \n, and $ would not match (since after ----- comes \r, not $). Would original consider \r as part of line and thus not match? Possibly. For now, strip trailing \r from each line (as is common).
    let mut line_no = 0;
    // Use split on b'\n'
