fn shannon(s: &[u8]) -> f64 {
    use std::collections::HashMap;
    let mut counts: HashMap<u8, usize> = HashMap::new();
    for &b in s {
        *counts.entry(b).or_insert(0) += 1;
    }
    let n = s.len() as f64;
    let mut ent = 0.0;
    for &c in counts.values() {
        let p = c as f64 / n;
        ent -= p * p.log2();
    }
    ent
}

